entries[44793] = { ["name"] = "Tome of Polymorph: Rabbit", ["text"] = "Binds when picked up\nClasses: Mage\nRequires Level 60\nUse: Teaches Polymorph: Rabbit.\nTransforms the enemy into a harmless rabbit, forcing it to scamper around for up to 50 sec. While wandering, the rabbit cannot attack or cast spells but will regenerate very quickly. Any damage will transform the target back into its normal form. Only one target can be polymorphed at a time. Only works on Beasts, Humanoids and Critters." }
